                q=deque([(r,c)]);cells=[]
                while q:
                    nr,nc=q.popleft();seen[nr,nc]=True;cells.append((nr,nc))
                    for dr,dc in DIRS:
                        a,b=nr+dr,nc+dc
                        if 0<=a<H and 0<=b<W and int(I[a,b])!=0 and not seen[a,b]:q.append((a,b))
                objs.append(cells)
    objset={(r,c):i for i,comp in enumerate(objs) for r,c in comp}
    seeds=[]
    for i,comp in enumerate(objs):
        ctr=[(r,c,int(I[r][c])) for r,c in comp if int(I[r][c])!=3]
        if len(ctr)!=1: continue
        sr,sc,v=ctr[0]
        seeds.append([comp,set((r,c) for r,c in comp)],v,(sr,sc))
    # sort candidates for write order: try by seed row asc, others
    def run(order_key):
        for _,mask,v,(sr,sc) in sorted(seeds,key=order_key):
            for dr,dc in DIRS:
                r,c=sr+dr,sc+dc
                while 0<=r<H and 0<=c<W:
