                    if int(O[r][c])==0: O[r][c]=v
                    elif m is not None: break          # own object -> pass through
                    else: break                         # other object -> stop
                    r+=dr; c+=dc
        return O
    res=run(lambda s:(s[1][0],))   # seed row ascending, top-left first
