        for cc in range(W): paint_line([(r,cc)],v); vert[(r,c)][v]=True
        for rr in range(H): paint_line([(rr,c)],v); horiz[(rr,c)][v]=True
    # resolve: try vertical priority then repaint horizontals? test variants
    return O,horizontal_set=horiz,_vert=_vert
